mapper.update:
UPDATE plugin_definition
SET dependency_jars_json = CAST(#{dependencyJarsJson} AS JSON), updated_at = CURRENT_TIMESTAMP
WHERE plugin_id = #{pluginId}

mapper.select:
SELECT * FROM plugin_definition
WHERE plugin_id LIKE #{keywordLike} OR display_name LIKE #{keywordLike}
ORDER BY plugin_id LIMIT #{limit} OFFSET #{offset}
